#include <iostream>
#include <fstream>
#include <memory>

class FileHandler {
public:
  FileHandler(const std::string& filename) : file_(filename.c_str(), std::ios::out) {
    if (!file_) {
      throw std::runtime_error("Could not open file!");
    }
  }
  ~FileHandler() {
    file_.close();
    std::cout << "File closed successfully."<<std::endl;
  }
  std::ofstream& getFile() { return file_; }
private:
  std::ofstream file_;
};

int main() {
  try {
    FileHandler file("mydata.txt");
    file.getFile() << "Some data to write";
  } catch (const std::runtime_error& error) {
    std::cerr << "Error: " << error.what() << std::endl;
    return 1;
  }
  return 0;
}
